// Apenas dados fictícios. Não ler CRM/WhatsApp e não acionar APIs externas.
const tenant = 'client0-demo';
const cases = [
  {id:'Q001', company_id:tenant, kind:'quote', days_waiting:8, opt_in:true, opt_out:false, template_approved:true, within_service_window:false},
  {id:'Q002', company_id:tenant, kind:'quote', days_waiting:10, opt_in:false, opt_out:false, template_approved:true, within_service_window:false},
  {id:'Q003', company_id:tenant, kind:'quote', days_waiting:8, opt_in:true, opt_out:true, template_approved:true, within_service_window:false},
  {id:'Q004', company_id:tenant, kind:'quote', days_waiting:1, opt_in:true, opt_out:false, template_approved:true, within_service_window:false},
  {id:'L001', company_id:tenant, kind:'inbound_lead', days_waiting:0, opt_in:true, opt_out:false, template_approved:false, within_service_window:true},
  {id:'L002', company_id:tenant, kind:'inbound_lead', days_waiting:0, opt_in:false, opt_out:false, template_approved:false, within_service_window:true},
  {id:'Q005', company_id:tenant, kind:'quote', days_waiting:7, opt_in:true, opt_out:false, template_approved:false, within_service_window:false},
  {id:'Q001', company_id:tenant, kind:'quote', days_waiting:8, opt_in:true, opt_out:false, template_approved:true, within_service_window:false},
  {id:'Q006', company_id:'other-tenant', kind:'quote', days_waiting:9, opt_in:true, opt_out:false, template_approved:true, within_service_window:false}
];
return cases.map(x=>({json:x}));

// Políticas determinísticas. NUNCA enviar ou gerar efeito externo.
const config = {company_id:'client0-demo', min_days_quote:3, simulation_only:true, max_actions:10};
const seen = new Set();
const decisions = $input.all().map(({json:record})=>{
  const id = String(record.id ?? '');
  const key = String(record.company_id ?? '')+':'+id+':'+String(record.kind ?? '');
  let status='blocked_invalid', reason='invalid_record', draft=null;
  if (!id || !['quote','inbound_lead'].includes(record.kind)) {
    reason='invalid_record';
  } else if (record.company_id!==config.company_id) {
    status='blocked';reason='tenant_scope';
  } else if (seen.has(key)) {
    status='blocked';reason='duplicate_event';
  } else if (record.opt_out===true) {
    status='blocked';reason='opt_out';
  } else if (record.opt_in!==true) {
    status='blocked';reason='no_opt_in';
  } else if (record.kind==='quote' && (!Number.isInteger(record.days_waiting) || record.days_waiting<config.min_days_quote)) {
    status='deferred';reason='follow_up_not_due';
  } else if (record.within_service_window!==true && record.template_approved!==true) {
    status='blocked';reason='template_required';
  } else if (record.kind==='quote') {
    status='draft_ready';reason='quote_follow_up';
    draft='Olá! Gostaríamos de saber se há alguma dúvida sobre o orçamento. Podemos ajudar?';
  } else {
    status='draft_ready';reason='inbound_qualification';
    draft='Olá! Qual serviço você procura e para qual região?';
  }
  seen.add(key);
  return {company_id:String(record.company_id ?? ''),fixture_id:id,kind:record.kind,status,reason,draft,dispatch:'disabled',simulation_only:true,idempotency_key:key};
});
const eligible=decisions.filter(x=>x.status==='draft_ready');
if (eligible.length>config.max_actions) throw Error('Simulation policy: quota exceeded');
return decisions.map(x=>({json:x}));

const rows=$input.all().map(x=>x.json);
const totals={};
for(const r of rows) totals[r.reason]=(totals[r.reason]||0)+1;
if(rows.length!==9) throw Error('Synthetic fixture count changed');
if(rows.some(r=>r.dispatch!=='disabled'||r.simulation_only!==true)) throw Error('Unsafe: dispatch enabled');
if(rows.filter(r=>r.status==='draft_ready').length!==2) throw Error('Unexpected ready count');
if(totals.tenant_scope!==1 || totals.opt_out!==1 || totals.no_opt_in!==2 || totals.duplicate_event!==1 || totals.template_required!==1 || totals.follow_up_not_due!==1) throw Error('Policy regression');
return [{json:{
  sandbox:true,
  outbound_messages_sent:0,
  tenants_processed:['client0-demo'],
  assessed:rows.length,
  drafts_prepared:2,
  decisions:totals,
  results:rows
}}];
